   139→      "#" + wid + "{" +
   140→        "background:" + cfg.backgroundColor + " !important;" +
   141→        "color:" + cfg.textColor + " !important;" +
   142→        "border-radius:" + rad + " !important;" +
   143→        "padding:24px !important;" +
   144→        "border:1px solid #e1e3e5 !important;" +
   145→        "max-width:480px;" +
   146→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
   147→        "box-sizing:border-box !important;" +
   148→      "}" +
   149→      "#" + wid + " *{box-sizing:border-box !important}" +
   150→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
   151→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
   152→      "#" + wid + " .zcc-input{" +
   153→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
   154→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
   155→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
   156→      "}" +
   157→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
   158→      "#" + wid + " .zcc-btn{" +
   159→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   160→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
   161→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
   162→      "}" +
   163→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
   164→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   165→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
   166→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
   167→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
   168→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
   169→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
   170→      "#" + wid + " .zcc-wl-input{" +
   171→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
   172→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
   173→      "}" +
   174→      "#" + wid + " .zcc-wl-btn{" +
   175→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
   176→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
   177→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
   178→      "}" +
   179→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
   180→      (cfg.customCss || "");
