   313→  // ── Inline position ─────────────────────────────────────────────────────────
   314→  function renderInline(cfg, WID, rad) {
   315→    injectCss(WID, cfg, rad);
   316→    container.id = WID;
   317→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
