   321→  // ── Floating position ────────────────────────────────────────────────────────
   322→  function renderFloating(cfg, WID, rad) {
   323→    // The original container becomes invisible (just an anchor)
   324→    container.style.display = "none";
   325→
   326→    injectCss(WID, cfg, rad);
   327→
   328→    // Additional styles for floating UI
   329→    var floatCss =
   330→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
   331→      "#" + WID + "-panel{" +
   332→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   333→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
   334→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
   335→      "}" +
   336→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
   337→      "#" + WID + "-panel .zcc-panel-header{" +
   338→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
   339→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
   340→      "}" +
   341→      "#" + WID + "-panel .zcc-panel-close{" +
   342→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
   343→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
   344→      "}" +
   345→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
   346→      "#" + WID + "-trigger{" +
   347→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   348→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
   349→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
   350→      "}" +
   351→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
   352→
   353→    var floatStyle = document.createElement("style");
   354→    floatStyle.textContent = floatCss;
   355→    document.head.appendChild(floatStyle);
   356→
   357→    // Build floating shell
   358→    var floatEl = document.createElement("div");
   359→    floatEl.id = WID + "-float";
   360→    floatEl.innerHTML =
   361→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
   362→        '<div class="zcc-panel-header">' +
   363→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
   364→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
   365→        '</div>' +
   366→        '<div id="' + WID + '">' +
   367→          buildWidgetInner(WID, cfg, cfg.buttonText) +
   368→        '</div>' +
   369→      '</div>' +
   370→      '<button id="' + WID + '-trigger" type="button">' +
   371→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
   372→        esc(cfg.buttonText || "Check Delivery") +
   373→      '</button>';
   374→
   375→    document.body.appendChild(floatEl);
   376→
   377→    // Wire toggle
   378→    var trigger = document.getElementById(WID + "-trigger");
   379→    var panel = document.getElementById(WID + "-panel");
   380→    var closeBtn = document.getElementById(WID + "-close");
   381→
   382→    if (trigger && panel) {
   383→      trigger.addEventListener("click", function () {
   384→        panel.classList.toggle("zcc-hidden");
   385→      });
   386→    }
   387→    if (closeBtn && panel) {
   388→      closeBtn.addEventListener("click", function () {
   389→        panel.classList.add("zcc-hidden");
   390→      });
   391→    }
   392→    // Close on outside click
