   402→  // ── Popup position ───────────────────────────────────────────────────────────
   403→  function renderPopup(cfg, WID, rad) {
   404→    injectCss(WID, cfg, rad);
   405→
   406→    var popupCss =
   407→      "#" + WID + "-overlay{" +
   408→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
   409→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
   410→      "}" +
   411→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
   412→      "#" + WID + "-modal{" +
   413→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
   414→        "max-width:480px !important;width:100% !important;position:relative !important;" +
   415→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
   416→      "}" +
   417→      "#" + WID + "-modal .zcc-modal-close{" +
   418→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
   419→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
   420→      "}" +
   421→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
   422→      "#" + WID + "-popup-trigger{" +
   423→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
   424→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
   425→        "cursor:pointer !important" +
   426→      "}" +
   427→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
   428→
   429→    var popupStyle = document.createElement("style");
   430→    popupStyle.textContent = popupCss;
   431→    document.head.appendChild(popupStyle);
   432→
   433→    // Trigger button renders in-place (inside the block)
   434→    container.innerHTML =
   435→      '<button id="' + WID + '-popup-trigger" type="button">' +
   436→        esc(cfg.heading) +
   437→      '</button>';
   438→
   439→    // Overlay + modal append to body
   440→    var overlay = document.createElement("div");
   441→    overlay.id = WID + "-overlay";
   442→    overlay.innerHTML =
   443→      '<div id="' + WID + '-modal">' +
   444→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
   445→        '<div id="' + WID + '">' +
   446→          buildWidgetInner(WID, cfg, cfg.buttonText) +
   447→        '</div>' +
   448→      '</div>';
   449→    document.body.appendChild(overlay);
   450→
   451→    var trigger = document.getElementById(WID + "-popup-trigger");
   452→    var closeBtn = document.getElementById(WID + "-modal-close");
   453→    var modal = document.getElementById(WID + "-modal");
   454→
   455→    function openPopup() { overlay.classList.add("zcc-open"); }
   456→    function closePopup() { overlay.classList.remove("zcc-open"); }
   457→
   458→    if (trigger) trigger.addEventListener("click", openPopup);
   459→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
   460→
   461→    // Close on overlay backdrop click (not modal content)
   462→    overlay.addEventListener("click", function (e) {
   463→      if (e.target === overlay) closePopup();
   464→    });
   465→
   466→    // Close on Escape key
   467→    document.addEventListener("keydown", function (e) {
   468→      if (e.key === "Escape") closePopup();
   469→    });
   470→
   471→    wireWidget(WID, cfg, API_BASE, SHOP);
   472→  }
   473→
   474→  function esc(str) {
   475→    return String(str)
   476→      .replace(/&/g, "&amp;")
   477→      .replace(/</g, "&lt;")
   478→      .replace(/>/g, "&gt;")
   479→      .replace(/"/g, "&quot;");
   480→  }
   481→
   482→  function escAttr(str) {
   483→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
   484→  }
   485→})();
   486→</script>
